const get = (node, path, transform) => {
  try {
    const val = path.split('.').reduce((o, k) => o[k], $(node).item.json);
    return transform ? transform(val) : val || "";
  } catch { return ""; }
};

return {
  message: [
    get('Aggregate', 'message', v => v.join(",")),
    get('Obtiene mensaje contexto', 'mensaje'),
    get('Obtiene nombre producto catalogo', 'producto')
  ].filter(Boolean).join(' ')
};

const agentItem = $('Agente Coordinador').first();
const native    = agentItem.metadata?.tokenUsage ?? {};

// El output final del agente está en el JSON (puede traer markdown fences)
const raw   = agentItem.json.output ?? '';
const clean = raw.replace(/^```json\\\\s*/i, '').replace(/\\\\s*```\\\\s*$/i, '').trim();

let parsed = {};
try { parsed = JSON.parse(clean); } catch { parsed = {}; }

const now = Date.now();
return {
  process_id:        $execution.id,
  model_name:        'gpt-4o-mini',
  prompt_tokens:     native.promptTokens     ?? 0,
  completion_tokens: native.completionTokens ?? 0,
  total_tokens:      native.totalTokens      ?? 0,
  ai_response:       parsed.replyText        ?? clean,
  completed_at:      now,
  created_at:        now,
  environment:       $vars.ENVIRONMENT        ?? 'prod',
  token_source:      'native'
}

const init = $('get_start_operation').first().json.value;
const end = $('get_end_operation').first().json.value;
const now = $now.hour
if (now >= init && now <= end){
  return [{ json: { open: true, hora_actual: now } }];
} else {
  return [{ json: { open: false, hora_actual: now } }];
}

