const items = $input.all();

const allProducts = items.flatMap((item) => item.json.order.product_items);

const retailerIds = allProducts.map((product) => product.product_retailer_id);

return [{
  json: {
    data: retailerIds
  }
}];

const items = $input.first().json.data
const result = items.map((item) => {
  return {
    name: item.name,
    image_url: item.image_url,
  };
});
return {data: result};

const rawOutput = $input.first().json.output || "";

const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);

let sanitizedString = rawOutput;
if (jsonMatch) {
  sanitizedString = jsonMatch[0];
}

try {
  const parsedData = JSON.parse(sanitizedString);

  return { 
    json: parsedData 
  };
} catch (error) {
  return {
    json: {
      destino: "Agente Asesor", // Enrutamiento por defecto por seguridad
      mensaje: "Error al parsear la intención",
      error_detalles: error.message,
      raw_output: rawOutput
    }
  };
}

